module TempAndHumi_drive(
	sys_clk,
	rst_n,
	data_valid,
	dht11_done,
	dht11);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	output [31:0] data_valid;
	output dht11_done;
	inout dht11;

	wire sys_clk;
	wire rst_n;
	reg [31:0] data_valid;
	reg dht11_done;
	wire dht11;

	//----Code starts here: integrated by Robei-----
	//状态机各个状态
	localparam	WAIT_1S		= 6'b000001 ,      
				START       = 6'b000010 ,      
				DELAY_10us  = 6'b000100 ,      
				REPLY       = 6'b001000 ,      
				DELAY_75us  = 6'b010000 ,      
				REV_data	= 6'b100000 ;      
	//时间参数定义
	localparam	T_1S = 25,                      //上电1s延时等待稳定，单位us，为方便仿真，我们代码中写为延时25us,正常应为999_999
				T_BE = 18 ,				           //主机拉低总线时间，单位us，   为方便仿真，我们代码中写为延时18us,正常应为17_999
				T_GO = 12	;				              //主机释放总线时间，单位us
	
	//reg定义								
	reg	[6:0]	cur_state	;					
	reg	[6:0]	next_state;					
	reg	[4:0]	cnt;					
	reg			dht11_out	;					
	reg			dht11_en;					
	reg			dht11_d1;				
	reg			dht11_d2;					
	reg			clk_us;					
	reg [21:0]	cnt_us;				
	reg [5:0]	bit_cnt;					
	reg [39:0]	data_temp;					
	 
	//wire定义		
	wire		dht11_in;					                                                        //双向总线输入
	wire		dht11_pos;					                                                    //上升沿
	wire		dht11_fall	;					                                                    //下降沿
	 
	//--双向端口使用方式
	assign	dht11_in = dht11;							                               //高阻态的话，则把总线上的数据赋给dht11_in
	assign	dht11 =  dht11_en ? dht11_out : 1'bz;		                   //使能1则输出，0则高阻态
	
	//--us时钟生成
	always @(posedge sys_clk or negedge rst_n)
	begin
	if(!rst_n)
	  begin
	  cnt <= 5'd0;
	  clk_us <= 1'b0;
	  end
	else 
	   begin
	     if(cnt == 5'd1)            //为便于仿真我们认为，两个时钟周期，即为1us;正常应为16
	       begin
	        cnt <= 5'd0;
	        clk_us <= ~clk_us; 
	       end
	    else
	       cnt <= cnt + 1'd1;
	   end
	end
	
	//--上升沿与下降沿检测电路
	assign	dht11_pos = ~dht11_d2 && dht11_d1;		
	assign	dht11_neg = ~dht11_d1 && dht11_d2;		
	
	always @(posedge clk_us or negedge rst_n)begin
		if(!rst_n)begin
			dht11_d1 <= 1'b0;				
			dht11_d2 <= 1'b0;			
		end
		else begin
			dht11_d1 <= dht11;				 
			dht11_d2 <= dht11_d1;			
		end
	end
	
	//状态机
	always @(posedge clk_us or negedge rst_n)begin
		if(!rst_n)		
			cur_state <= WAIT_1S;			
		else
			cur_state <= next_state;
	end
	
	always @(*)begin
		next_state = WAIT_1S;
		case(cur_state)
			WAIT_1S		:begin
				if(cnt_us == T_1S)					
					next_state = START;			
				else	
					next_state = WAIT_1S;		
			end	
			START       :begin	
				if(cnt_us == T_BE)				
					next_state = DELAY_10us;	
				else
					next_state = START;			
			end
			DELAY_10us  :begin					
				if(cnt_us == T_GO)				
					next_state = REPLY;			
				else
					next_state = DELAY_10us;	
			end
			REPLY       :begin
				if(cnt_us <= 'd500)begin		
					if(dht11_pos && cnt_us >= 'd10 && cnt_us <= 'd100)				   //上升沿，且低电平时间介于70~100us ，为便于仿真我们这里认为时间大于10即可，正常应为
						next_state = DELAY_75us;		
					else
						next_state = REPLY;				
				end	
				else	
					   next_state = START;					
			end	
			DELAY_75us  :begin	
				if(dht11_neg && cnt_us >= 'd10)		                                               //下降沿，且高电平时间大于70us，为便于仿真我们这里认为时间大于10即可
					next_state = REV_data;				
				else 	
					next_state = DELAY_75us;			
			end	
			REV_data	:begin	
				if(dht11_pos && bit_cnt == 'd40)begin		
					dht11_done = 1'b1;												                           //数据接收完成	
					next_state = START;end					
				else 	
					next_state = REV_data;				
			end	
			default:next_state = START;					
		endcase
	end	
	 
	always @(posedge clk_us or negedge rst_n)begin
		if(!rst_n)begin																
			dht11_en <= 1'b0;
			dht11_out <= 1'b0;
			cnt_us <= 22'd0;
			bit_cnt <=  6'd0;
			data_temp <= 40'd0;
			dht11_done <= 1'b0; 	
		end
		else 	
			case(cur_state)
				WAIT_1S		:begin
					dht11_en <= 1'b0;						                                                          //释放总线
					if(cnt_us == T_1S)						
						cnt_us <= 22'd0;					
					else
						cnt_us <= cnt_us + 1'd1;			
				end
				START		:begin
					dht11_en <= 1'b1;						                                                          //占用总线
					dht11_out <= 1'b0;						                                                          //输出低电平
					if(cnt_us == T_BE)		
						cnt_us <= 22'd0;					
					else		
						cnt_us <= cnt_us + 1'd1;			
				end		
				DELAY_10us	:begin		
					dht11_en <= 1'b0;						                                                           //释放总线
					if(cnt_us == T_GO)
						cnt_us <= 22'd0;					
					else                                    
						cnt_us <= cnt_us + 1'd1;            
				end	
				REPLY		:begin
					dht11_en <= 1'b0;						                                                           //释放总线
					if(cnt_us <= 'd500)begin				
						if(dht11_pos && cnt_us >= 'd10 && cnt_us <= 'd100)				       //上升沿，且低电平时间介于70~100us，为便于仿真我们这里认为时间大于10即可
							cnt_us <= 22'd0;				
						else
							cnt_us <= cnt_us + 1'd1;		
					end
					else 
						cnt_us <= 22'd0;					 
				end	
				DELAY_75us  :begin
					dht11_en <= 1'b0;						                                                           //释放总线
					if(dht11_neg && cnt_us >= 'd10)		                                                   //上升沿响应，且低电平时间大于70us，为便于仿真我们这里认为时间大于10即可
						cnt_us <= 22'd0;					
					else 	
						cnt_us <= cnt_us + 1'd1;			
				end
				REV_data	:begin
					dht11_en <= 1'b0;						                                                           //释放总线 
					if(dht11_pos && bit_cnt == 'd40)begin	
						bit_cnt <=  6'd0; 					
						cnt_us <= 22'd0;					
					end
					else if(dht11_neg)begin				 
						bit_cnt <= bit_cnt + 1'd1;			
						cnt_us <= 22'd0;					
						if(cnt_us <= 'd25)					                                                           //判断数据是0还是1  
							data_temp[39-bit_cnt] <= 1'b0;	
						else 
							data_temp[39-bit_cnt] <= 1'b1;	
					end
					else begin								
						bit_cnt <= bit_cnt;				
						data_temp <= data_temp;
						cnt_us <= cnt_us + 1'd1;			
					end
				end
				default:;		
			endcase
	end
	 
	
	always @(posedge clk_us or negedge rst_n)begin
		if(!rst_n)
			data_valid <= 32'd0;                                                                                    //判断接收到的数据是否符合规则
		else if((data_temp[7:0] == data_temp[39:32] + data_temp[31:24] +data_temp[23:16] + data_temp[15:8]))
			data_valid <= data_temp[39:8]; 		
		else
		    data_valid <= data_valid;			
		end
	
	
	
	
endmodule    //TempAndHumi_drive

